window.habar_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

const mkBtn=(lbl,w,ht,fill,bord,tc)=>{
  fill=fill||0x1a3a0a;bord=bord||0x3a7a1a;tc=tc||'#90d040';
  const bg=new A();bg.beginFill(fill,1);bg.lineStyle(1,bord);bg.drawRoundedRect(0,0,w,ht,4);bg.endFill();
  const t=new z(lbl,{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:tc,align:'center',wordWrap:true,wordWrapWidth:w-6});
  t.anchor.set(0.5,0.5);t.x=w/2;t.y=ht/2;
  const c=new e();c.addChild(bg,t);c.interactive=true;c.buttonMode=true;
  c.on('mouseover',()=>bg.tint=0xddeecc);c.on('mouseout',()=>bg.tint=0xffffff);
  c._bg=bg;c._txt=t;return c;
};

// Цвета редкости
const RARITY_COLORS = {common:0x4a6a3a, rare:0x3a4a8a, epic:0x6a2a8a, legendary:0x8a6a00};
const RARITY_NAMES  = {common:'ОБЫЧНЫЙ', rare:'РЕДКИЙ',  epic:'ЭПИЧЕСКИЙ', legendary:'ЛЕГЕНДАРНЫЙ'};

// ── Иконка предмета в дропе ────────────────────────────────────────
habar_elements.lib.Loot_icon=class extends e{
  constructor(rarity){
    super();rarity=rarity||'common';
    const col=RARITY_COLORS[rarity]||0x4a6a3a;
    const bg=new A();bg.beginFill(col,0.25);bg.lineStyle(1,col,0.8);bg.drawRoundedRect(0,0,50,50,4);bg.endFill();
    const ic=new z('',{fontFamily:'Arial',fontSize:26,align:'center'});ic.anchor.set(0.5,0.5);ic.x=25;ic.y=25;
    this[ic.name='icon_txt']=ic;this.addChild(bg,ic);
  }
};

// ── Карточка хабара ────────────────────────────────────────────────
habar_elements.lib.Habar_card=class extends e{
  constructor(){
    super();
    this.bg_mc=new A();this._drawBg('common',false);this.addChild(this.bg_mc);
    // Большая иконка контейнера
    const cic=new z('',{fontFamily:'Arial',fontSize:72,align:'center'});cic.anchor.set(0.5,0);cic.x=140;cic.y=16;this[cic.name='chest_icon']=cic;this.addChild(cic);
    // Бейдж редкости
    const rbg=new A();rbg.beginFill(0x1a1a1a,1);rbg.lineStyle(1,0x333333);rbg.drawRoundedRect(0,0,130,22,3);rbg.endFill();rbg.x=75;rbg.y=104;
    const rt=new z('',{fontFamily:'Southbank LT',fontSize:10,fontWeight:'bold',fill:'#aaaaaa',align:'center'});rt.anchor.set(0.5,0.5);rt.x=65;rt.y=11;
    const rw=new e();rw.addChild(rbg,rt);rw.x=75;rw.y=104;this[rt.name='rarity_txt']=rt;this[rw.name='rarity_badge']=rw;this.addChild(rw);
    // Название и описание
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:16,fontWeight:'bold',fill:'#c8d840'});nt.x=10;nt.y=136;this[nt.name='name_txt']=nt;this.addChild(nt);
    const dt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#6a8a4a',wordWrap:true,wordWrapWidth:260});dt.x=10;dt.y=160;this[dt.name='desc_txt']=dt;this.addChild(dt);
    // Возможный дроп (preview лут иконок)
    const loot=new e();loot.x=10;loot.y=200;
    for(let i=0;i<5;i++){
      const li=new habar_elements.lib.Loot_icon();li.x=i*56;loot['li_'+i]=li;loot.addChild(li);
    }
    this[loot.name='loot_row']=loot;this.addChild(loot);
    // Счётчик
    const ct=new z('x0',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#8aaa50',align:'right'});ct.x=260;ct.y=262;this[ct.name='count_txt']=ct;this.addChild(ct);
    // Цена
    const pt=new z('',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#c8a030'});pt.anchor.set(0.5,0);pt.x=140;pt.y=280;this[pt.name='price_txt']=pt;this.addChild(pt);
    // Кнопки
    const open=mkBtn('ОТКРЫТЬ',120,36,0x1e4a00,0x4a9a10,'#a0e040');open.x=10;open.y=310;this[open.name='butt_open']=open;
    const buy=mkBtn('КУПИТЬ ×1',120,36,0x1a3a00,0x3a7a10,'#80c030');buy.x=148;buy.y=310;this[buy.name='butt_buy']=buy;
    this.addChild(open,buy);
  }
  _drawBg(rarity,hover){
    const col=RARITY_COLORS[rarity]||0x4a6a3a;
    this.bg_mc.clear();
    this.bg_mc.beginFill(hover?0x0e1e0a:0x080e05,hover?0.98:0.95);
    this.bg_mc.lineStyle(hover?2:1,col,hover?0.9:0.6);
    this.bg_mc.drawRoundedRect(0,0,280,358,6);this.bg_mc.endFill();
  }
  setRarity(r){
    const col=RARITY_COLORS[r]||0x4a6a3a;
    const name=RARITY_NAMES[r]||'';
    this._drawBg(r,false);
    this.rarity_txt.text=name;
    const rbg=this.rarity_badge.children[0];
    rbg.clear();rbg.beginFill(col,0.3);rbg.lineStyle(1,col,0.9);rbg.drawRoundedRect(0,0,130,22,3);rbg.endFill();
    this.rarity_txt.style.fill='#'+col.toString(16).padStart(6,'0');
  }
};

// ── Оверлей результата открытия ────────────────────────────────────
habar_elements.lib.Open_result=class extends e{
  constructor(){
    super();
    const dimmer=new A();dimmer.beginFill(0x000000,0.7);dimmer.drawRect(0,0,1200,524);dimmer.endFill();this.addChild(dimmer);
    const panel=new A();panel.beginFill(0x0a1808,0.98);panel.lineStyle(2,0x3a7a1a,0.9);panel.drawRoundedRect(200,80,800,360,8);panel.endFill();this.addChild(panel);
    const ttl=new z('ХАБАР ПОЛУЧЕН!',{fontFamily:'Southbank LT',fontSize:20,fontWeight:'bold',fill:'#c8e040',align:'center',letterSpacing:4,dropShadow:true,dropShadowDistance:3,dropShadowColor:'#000'});
    ttl.anchor.set(0.5,0);ttl.x=600;ttl.y=100;this.addChild(ttl);
    const st=new z('',{fontFamily:'Southbank LT',fontSize:14,fill:'#8aaa50',align:'center'});st.anchor.set(0.5,0);st.x=600;st.y=136;this[st.name='sub_txt']=st;this.addChild(st);
    // Слоты под найденные предметы (до 5)
    const slots=new e();slots.x=220;slots.y=180;
    for(let i=0;i<5;i++){
      const sl_bg=new A();sl_bg.beginFill(0x0c1a08,1);sl_bg.lineStyle(1,0x2a4a1a);sl_bg.drawRoundedRect(0,0,130,130,6);sl_bg.endFill();sl_bg.x=i*146;
      const sl_ic=new z('',{fontFamily:'Arial',fontSize:56,align:'center'});sl_ic.anchor.set(0.5,0.5);sl_ic.x=sl_bg.x+65;sl_ic.y=65;
      const sl_nt=new z('',{fontFamily:'Arial',fontSize:10,fill:'#a0c060',align:'center',wordWrap:true,wordWrapWidth:124});sl_nt.anchor.set(0.5,0);sl_nt.x=sl_bg.x+65;sl_nt.y=84;
      slots['sl_bg_'+i]=sl_bg;slots['sl_ic_'+i]=sl_ic;slots['sl_nt_'+i]=sl_nt;
      slots.addChild(sl_bg,sl_ic,sl_nt);
    }
    this[slots.name='item_slots']=slots;this.addChild(slots);
    const close=mkBtn('ЗАБРАТЬ',160,40,0x1e4a00,0x4a9a10,'#a0e040');close.x=520;close.y=390;this[close.name='butt_take']=close;this.addChild(close);
    this.visible=false;
  }
};

// ── Главное окно Хабара ────────────────────────────────────────────
habar_elements.lib.Habar_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x060c04,0.97);wb.lineStyle(2,0x284a18,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();this.addChild(wb);
    const hb=new A();hb.beginFill(0x081802,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x284a18,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);this.addChild(hb,hl);
    const ttl=new z('ХАБАР',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#b8d840',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});ttl.x=20;ttl.y=12;this.addChild(ttl);
    const stl=new z('Открывай контейнеры и получай снаряжение',{fontFamily:'Arial',fontSize:11,fill:'#3a5a2a',fontStyle:'italic'});stl.x=200;stl.y=17;this.addChild(stl);
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;cl.interactive=true;cl.buttonMode=true;cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // 4 карточки хабара в ряд
    const cards=new e();cards.x=20;cards.y=54;
    for(let i=0;i<4;i++){
      const c=new habar_elements.lib.Habar_card();
      c.x=i*(280+13);cards['card_'+i]=c;cards.addChild(c);
    }
    this[cards.name='habar_cards']=cards;this.addChild(cards);
    // Результат
    const res=new habar_elements.lib.Open_result();res.x=0;res.y=0;
    this[res.name='open_result']=res;this.addChild(res);
    // Энергия и монеты подсказка
    const hint=new z('Тушёнка тратится на открытие. Найденные предметы автоматически добавляются в инвентарь.',{fontFamily:'Arial',fontSize:11,fill:'#2a4a1a',fontStyle:'italic'});
    hint.x=20;hint.y=422;this.addChild(hint);
  }
};

habar_elements.lib.habar_elements=class extends n{
  constructor(){super({duration:1,framerate:30});const b=new habar_elements.lib.Habar_win();this[b.name='habar_win']=b;this.addChild(b);}
};
habar_elements.stage=habar_elements.lib.habar_elements}};
